from decimal import Decimal

from pyspark.sql import functions as F


def tsql_decimal_div(left, right, result_type, scale):
    """Decimal division the SQL Server way: extra digits are cut off, not rounded.

    Spark rounds (2.0 / 3 -> 0.666667); SQL Server truncates (0.666666). Truncate Spark's
    quotient, then step back once if Spark's own rounding had already carried it too far.
    A zero divisor gives NULL.
    """
    step = F.lit(Decimal(1).scaleb(-scale)).cast(f"decimal({scale + 1},{scale})")
    quotient = left / right
    cut = quotient - (quotient % step)
    overshoot = F.abs(cut * right) > F.abs(left)
    cut = F.when(overshoot, cut - F.signum(quotient).cast("decimal(1,0)") * step).otherwise(cut)
    return cut.cast(result_type)


def run(spark, tables):
    spark.conf.set("spark.sql.decimalOperations.allowPrecisionLoss", "false")
    df = tables['policy'].alias('p')
    df = df.join(tables['claims'].alias('c'), on=(F.col("c.IDpol") == F.col("p.IDpol")), how="left")
    df = df.groupBy(F.upper(F.rtrim(F.col("p.VehBrand"))).alias("__g0")).agg(
        F.min(F.col("p.VehBrand")).alias("__r0"),
        (F.sum(F.col("p.VehAge")) / F.count(F.col("p.VehAge"))).cast("int").alias("__a0"),
        (F.sum(F.col("p.DrivAge")) / F.count(F.col("p.DrivAge"))).cast("int").alias("__a1"),
        tsql_decimal_div(F.sum(F.col("c.ClaimAmount")).cast("decimal(38,2)"), F.count(F.col("c.ClaimAmount")).cast("decimal(10,0)"), "decimal(38,6)", 6).alias("__a2"),
        F.count(F.col("c.IDpol")).cast("int").alias("__a3"),
    )
    df = df.select(
        F.col("__r0").alias('VehBrand'),
        F.col("__a0").alias('AvgVehAge'),
        F.col("__a1").alias('AvgDrivAge'),
        F.col("__a2").alias('AvgClaim'),
        F.col("__a3").alias('Claims'),
    )
    return df


